static const u16 kResN = (u16)(sizeof(kRes) / sizeof(kRes[0]));
[[gnu::used]] void n2a_frame(void) {
    g_engine_mode = 1u;
    if (g_resume == 0u) { f_C79E(); return; }
    u16 lo = 0u, hi = kResN;
    while (lo < hi) { const u16 mid = (u16)((lo + hi) / 2u); if (kRes[mid].a < g_resume) { lo = (u16)(mid + 1u); } else { hi = mid; } }
    if (lo < kResN && kRes[lo].a == g_resume) { kRes[lo].fn(); return; }
    g_resume = 0u;
}
[[gnu::used]] void game_main(void) {
    for (;;) { n2a_frame(); if (halted) { return; } }
}
